package dev.kelmagic.client;
import dev.kelmagic.research.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import java.util.*;
/** Complete paginated creative reference, never a grant of survival knowledge. */
public final class ResearchOpeningGuide {
 static String item(String id){if(id.startsWith("#"))return id.equals("#minecraft:saplings")?"любой саженец (тег minecraft:saplings)":id;return BuiltInRegistries.ITEM.get(ResourceLocation.parse(id)).getDescription().getString();}
 public static String describe(ResearchCatalog.Node n){var s=new StringBuilder("СПОСОБ ОТКРЫТИЯ\n\n");if(n.sealed())return s+"Запись запечатана. В текущей версии нет доступного пути исследования. Творческий кодекс показывает её как справочную; выполнить гипотезу в выживании пока нельзя.";if(n.free())return s+switch(n.id()){case "mana_core"->"Доступно с начала игры, гипотеза не нужна. Изготовьте ядро по схеме. Изготовление ядра открывает вкладку «Материалы».";case "archivists_codex"->"Доступно с начала игры. Изготовьте кодекс по схеме; слова сохраняются на столе архивариуса. Отдельной гипотезы нет.";case "archivist_table"->"Доступно с начала игры. Изготовьте стол по схеме. Монокль — часть этой записи, его схема среди рецептов этой записи. Поставьте кодекс на стол для работы с гипотезами и образцами.";default->"Отдельная гипотеза не требуется. Используйте схему и описание этой записи.";};
 if(!n.parents().isEmpty())s.append("Сначала открыть: ").append(String.join(", ",n.parents().stream().map(id->Research.name(ResearchCatalog.BY_ID.get(id))).toList())).append(".\n\n");
 s.append("Вкладка: ").append(switch(n.tab()){case "origins"->"Основы (есть с начала)";case "materials"->"Материалы (изготовить ядро маны)";case "infusion"->"Наполнение (зачаровать предмет на столе зачарований: достижение minecraft:story/enchant_item)";case "sound"->"Отзвук (получить любую музыкальную пластинку в инвентарь)";case "equipment"->"Облачения (открыть магический слиток или ткань)";case "great"->"Потусторонние знания (открыть станцию наполнения, магический слиток и магическую ткань)";default->n.tab();}).append(".\n\n");
 String word=Research.requiredWord(n);if(!word.isEmpty())s.append("Заранее расшифровать «").append(word).append("» и сохранить слово в кодексе при себе или на столе.\n\n");
 s.append("Взять один лист бумаги и кодекс. Выбрать узел: записать гипотезу. Лист должен оставаться при себе во время каждого шага; выполнить шаги строго по порядку.\n\n");int i=0;for(var st:n.steps()){s.append(++i).append(") ");if(st.kind().equals("observation")){s.append(st.hint()).append("\nТочное действие: ").append(String.join(" ИЛИ ",st.signals().stream().map(ResearchOpeningGuide::signal).toList()));}else if(st.kind().equals("material")){s.append("У стола архивариуса иметь гипотезу и образцы: ").append(count(st.samples().isEmpty()?List.of(st.item()):st.samples())).append(". Подойти к столу: образцы расходуются автоматически; либо ПКМ гипотезой по столу.");}else if(st.kind().equals("resonance")){s.append("На станции наполнения: в центр ").append(item(st.center())).append("; вокруг ").append(count(st.samples())).append(". Точную раскладку смотрите в схеме. Произнести «").append(st.word()).append("», дождаться окончания. Гипотеза при себе, в словах не подменять звуки. Первый опыт оставит один образец; серийный выход показан в схеме.");}s.append("\n\n");}
 s.append("Завершение: лист превратится в открытие. Взять его в руку и ПКМ, чтобы сохранить исследование. Чужой лист не засчитывается. Творческая книга не выдаёт это знание обычному персонажу.");if(n.id().equals("archivist_cabinet"))s.append("\n\nОдно открытие даёт ОБА шкафа: обычный и рукописей, дополнительная гипотеза не нужна.");return s.toString();}
 static String count(List<String> ids){var m=new LinkedHashMap<String,Integer>();for(String id:ids)m.merge(id,1,Integer::sum);return String.join(", ",m.entrySet().stream().map(e->e.getValue()+" × "+item(e.getKey())).toList());}
 static String signal(String v){if(v.equals("craft:minecraft:white_wool"))return "изготовить белую шерсть из четырёх нитей; стрижка овцы не засчитывается";if(v.equals("craft:minecraft:gold_nugget"))return "разобрать золотой слиток на золотые самородки";if(v.startsWith("craft:"))return "изготовить «"+item(v.substring(6))+"» на верстаке после записи гипотезы";if(v.startsWith("carry:"))return "получить в инвентарь «"+item(v.substring(6))+"» и подождать до 0,5 секунды";if(v.startsWith("wear:"))return "надеть «"+item(v.substring(5))+"» и для нагрудника пробежать, для шлема выйти под открытое небо, для поножей пройтись, для обуви прыгнуть/упасть с небольшой высоты";return switch(v){case "record_spell"->"включить запись скриптера ПКМ, произнести корректное обычное высказывание и ещё раз ПКМ для сохранения; великое высказывание не засчитывается";case "touch:amethyst"->"ПКМ по аметистовому блоку";case "transform:torch"->"превратить факел словом nov";case "transform:lantern"->"превратить морской фонарь словом nov";default->v;};}
 private ResearchOpeningGuide(){}
}
